import{_ as s,C as i,o as r,c as n,j as t,a as o,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const w=JSON.parse('{"title":"Leak history in CI","description":"How Piwi follows each resource leak across runs, decides when it is fixed or new to a branch, and blocks a merge or comments on a pull request with it.","frontmatter":{"title":"Leak history in CI","description":"How Piwi follows each resource leak across runs, decides when it is fixed or new to a branch, and blocks a merge or comments on a pull request with it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/leak-history.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/leak-history.html"}],["meta",{"property":"og:title","content":"Leak history in CI | Piwi for Playwright"}],["meta",{"property":"og:description","content":"How Piwi follows each resource leak across runs, decides when it is fixed or new to a branch, and blocks a merge or comments on a pull request with it."}]]},"headers":[],"relativePath":"features/leak-history.md","filePath":"features/leak-history.md","lastUpdated":1794342566000}'),d={name:"features/leak-history.md"};function c(p,e,u,f,k,g){const a=i("Needs");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"leak-history-in-ci",tabindex:"-1"},[o("Leak history in CI "),t("a",{class:"header-anchor",href:"#leak-history-in-ci","aria-label":'Permalink to "Leak history in CI"'},"​")],-1)),h(a,{reporter:"",fixtures:""}),e[1]||(e[1]=l('<p>The <a href="./resource-leaks.html">resource leaks</a> each run reports are kept across runs, so a pull request can be held to the leaks it adds, and a fix is known to have held.</p><h2 id="each-finding-s-history" tabindex="-1">Each finding&#39;s history <a class="header-anchor" href="#each-finding-s-history" aria-label="Permalink to &quot;Each finding&#39;s history&quot;">​</a></h2><p>Each finding keeps a history: the run it was first seen in and the runs that showed it. A finding is known by the line or fixture that opened it, so renaming its test or fixture, or opening and closing another context in its file, keeps its history. A leak that an edit above its line moved keeps it too.</p><p>Only a full run of the default branch changes a finding. A leak is fixed once five such runs came without it, each able to have shown it: with the fixtures on, its report not cut at the 100 findings the dashboard keeps, and a test of the leak&#39;s file passed while none failed, was interrupted or did not run. What such a test left open is never judged, so with one anywhere in the run, a leak a fixture or a helper opened is not counted either. Such a run that shows the leak again reopens it. Any other run, a partial run or a branch forked before the fix, only adds its showing. On the Resources tab each finding says whether it is new to the base branch (the pull request&#39;s target, else the default branch), or since which run it has been there.</p><h2 id="where-ci-reads-it" tabindex="-1">Where CI reads it <a class="header-anchor" href="#where-ci-reads-it" aria-label="Permalink to &quot;Where CI reads it&quot;">​</a></h2><p>Three places read it:</p><ul><li><a href="/guide/ci.html#blocking-a-merge"><code>piwi gate</code></a>: <code>--max-leaks &lt;n&gt;</code> fails when the run left more than <code>n</code> objects open, counted per opening line; <code>--max-new-leaks &lt;n&gt;</code>, when more than <code>n</code> were never seen on the base branch. A run that sent no resource report fails either rule rather than passing on silence, and so does a run of a project that declined the <strong>Resources</strong> capability, whose leaks are not measured. Neither counts a lingering object.</li><li>The <a href="./pr-feedback.html">pull-request comment</a> lists each leak the branch introduces under <strong>Left open by this change</strong>.</li><li>Agents read <code>list_resource_findings</code> and <code>get_resource_profile</code> over <a href="/reference/mcp-tools.html">MCP</a>.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-new-leaks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./resource-leaks.html">Resource leaks</a>: what a run reports, and how to fix each finding</li><li><a href="./pr-feedback.html">Pull-request feedback</a>: the comment that lists the leaks a branch adds</li><li><a href="/guide/ci.html#blocking-a-merge">CI &amp; sharding</a>: the gate&#39;s other policies</li></ul>',10))])}const b=s(d,[["render",c]]);export{w as __pageData,b as default};
